    H,W=len(g),len(g[0])
    # connected comps of nonzero ignoring 0
    import collections
    def nb(r,c): return [(r+dr,c+dc) for dr in(-1,0,1) for dc in(-1,0,1) if (dr or dc)]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
