                    seen.add((x,y)); comp.append((x,y))
                    for xx,yy in nb(x,y): st.append((xx,yy))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                res[(col,min(rs),min(cs),max(rs),max(cs))]=comp
