def solve(g):
    items=[]
    for fcol,b in frames(g):
        r0,r1,c0,c1=b
        inn=[[g[r][c] for c in range(c0+1,c1)] for r in range(r0+1,r1)]
        noisy=sum(1 for row in inn for v in row if v!=0 and v!=fcol)
        mask=[[[v!=0 for v in row] for row in inn]] * 0 + [[[bool(v) for v in row] for row in inn]]
        items.append(dict(col=fcol,pos=b,mask=mask,noisy=noisy,inn=inn))
    tmpl=[i for i in items if i['noisy']][0]
    out=[row[:] for row in g]
    for t in items:
        if t is tmpl or t['pos']==tmpl['pos']: continue
        ih,iw=len(t['mask']),len(t['mask'][0])
        tr,tc=t['pos']
        for i,rowm in enumerate(tmpl['mask']):
            for j,v in enumerate(rowm[0]):
                rr,cc=tr+i+1,tc+j+1
                out[rr][cc]= tmpl['col'] if v else 0
    return out
