def solve(g):
    fr=frames(g)
    out=[row[:] for row in g]
    srcs=[f for f in fr if any(v==f['col'] for rowm in f['inn'] for v in rowm)]
    for f in srcs:
        ih,iw=f['r1']-f['r0']-1,f['c1']-f['c0']-1
        msk=[[1 if v else 0 for v in rowm] for rowm in f['inn']]
        # clear noise inside this source's own interior
        for i,rowm in enumerate(f['inn']):
            for j,v in enumerate(rowm):
                if v==f['col']:
                    out[f['r0']+1+i][f['c0']+1+j]=0
        for t in fr:
            pr,pc=t['r0'],t['c0']
            th,tw=len(t['inn']),len(t['inn'][0])
            if (th,tw)!=(ih,iw): continue
            if not all(v==0 for rowm in t['inn'] for v in rowm): continue
            for i in range(ih):
                for j in range(iw):
                    out[pr+1+i][pc+1+j]= t['col'] if msk[i][j] else 0
    return out
