def rel(mask,h,w):
    # canonical: sorted normalized set of (i,j)
    pts=[(i,j) for i in range(h) for j in range(w) if mask[i][j]]
    return tuple(sorted(pts))
def norm(pts):
    m=min(p[0] for p in pts);n=min(p[1] for p in pts)
    return tuple(sorted((a-m,b-n) for a,b in pts))
